svg.script:
(function () {
  try {
    if (typeof window === "undefined" || typeof document === "undefined") return;
    var svg = document.querySelector("svg") || document.documentElement;
    if (!svg || typeof svg.setCurrentTime !== "function") return;
    var DUR = 6000;
    window.__DUR_MS = DUR;
    window.__POSTER_MS = 5500;
    window.__ready = (document.fonts && document.fonts.ready) || Promise.resolve(true);
    window.__seek = function (ms) { var t = ((ms % DUR) + DUR) % DUR; svg.pauseAnimations(); svg.setCurrentTime(t / 1000); return t; };
    window.__play = function () { svg.unpauseAnimations(); };
    if (window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches) window.__seek(window.__POSTER_MS);
  } catch (e) {}
})();
